<script setup>
import {computed,ref,watch} from 'vue'
import {predicatePrograms,validateProgram,forwardPredicateSteps,sldPredicateSteps} from '../services/predicate-inference.mjs'
import SimulationControls from './SimulationControls.vue'
import PredicateCode from './PredicateCode.vue'
const props=defineProps({mode:{type:String,default:'forward'}}),mode=ref(props.mode),preset=ref('kings'),program=ref(predicatePrograms.kings),step=ref(0),input=ref(JSON.stringify(predicatePrograms.kings,null,2)),error=ref('')
const trace=computed(()=>Array.from(mode.value==='forward'?forwardPredicateSteps(program.value):sldPredicateSteps(program.value))),state=computed(()=>trace.value[Math.min(step.value,trace.value.length-1)]),key=computed(()=>JSON.stringify([mode.value,program.value]))
watch(key,()=>step.value=0);watch(preset,()=>{program.value=predicatePrograms[preset.value];input.value=JSON.stringify(program.value,null,2);error.value=''})
function apply(){try{const p=JSON.parse(input.value);validateProgram(p);program.value=p;error.value=''}catch(e){error.value=e.message}}
const message=computed(()=>{const s=state.value;if(s.phase==='fixedpoint')return `Đã đạt điểm cố định của các luật khẳng định. ${s.answers.length?'Các câu trả lời thu được ở bên dưới.':'Không có phép thế trả lời từ bao đóng này. Điều đó không chứng minh phủ định truy vấn.'}`;if(s.phase==='finished')return `${s.answers.length?'Đã tìm được câu trả lời.':'Không tìm được câu trả lời theo phép duyệt này.'} Truy vấn không được ngầm hiểu là đúng với mọi đối tượng.`;if(s.phase==='budget')return `Đã chạm giới hạn quan sát. ${s.answers.length?'Các câu trả lời đã tìm vẫn hợp lệ, nhưng chưa khẳng định đã liệt kê hết.':'Chưa thể kết luận phủ định hoặc vô nghiệm.'}`;if(s.phase==='depth')return 'Nhánh đã chạm giới hạn độ sâu. Bộ xem quay lui để thử nhánh khác, không coi nhánh này đã chứng minh thất bại.';if(s.phase==='match')return 'Các tiền đề cùng khớp dưới một phép thế chung. Chưa thêm đầu luật ở bước này.';if(s.phase==='derive')return `Thêm sự thực mới ${s.head}. Các sự thực trùng không được thêm lại.`;if(s.phase==='goal')return `Chọn mục tiêu trái nhất ${s.selected}.`;if(s.phase==='resolve')return 'Đổi tên biến của luật để tách biệt, hợp nhất đầu luật với mục tiêu, rồi áp dụng phép thế lên cả thân luật lẫn mọi mục tiêu còn lại.';if(s.phase==='answer')return 'Danh sách mục tiêu rỗng, nhánh chứng minh thành công. Chỉ lấy ràng buộc của biến xuất hiện trong truy vấn để trả lời.';if(s.phase==='backtrack')return 'Khôi phục danh sách mục tiêu và phép thế của nhánh cha trước khi xét luật kế tiếp.';return mode.value==='forward'?'Bắt đầu từ các sự thực nền. Luật chỉ suy ra các kết luận khẳng định.':'Bắt đầu từ truy vấn. Mỗi mục tiêu dùng một bản sao luật có biến tách biệt.'})
</script>
<template><section class="math-lab predicate-inference" aria-label="Mô phỏng suy luận vị từ"><div class="infer-config"><label>Phương pháp<select v-model="mode"><option value="forward">Suy luận tiến</option><option value="sld">SLD, duyệt theo chiều sâu</option></select></label><label>Cơ sở tri thức<select v-model="preset"><option v-for="(p,k) in predicatePrograms" :key="k" :value="k">{{ p.title }}</option></select></label></div><p class="query-term">Truy vấn: {{ program.query }}</p><details class="knowledge-input"><summary>Xem và đổi cơ sở tri thức</summary><p>Biến viết dạng ?x. facts chứa câu nền, rules chứa head và body. Bộ suy luận tiến yêu cầu các biến đầu luật xuất hiện ở thân. Không hỗ trợ phủ định trong thân, bằng nhau hoặc suy luận theo thế giới đóng.</p><label>Dữ liệu JSON<textarea v-model="input" rows="10" spellcheck="false"/></label><button type="button" @click="apply">Dùng cơ sở tri thức</button><p v-if="error" role="alert">{{ error }}</p></details><SimulationControls v-model="step" :max="trace.length-1" :reset-key="key"/><p class="predicate-status" role="status">{{ message }}</p><div class="inference-state"><article><h4>{{ mode==='forward'?'Sự thực đã biết':'Danh sách mục tiêu, chọn từ trên xuống' }}</h4><ol><li v-for="(f,i) in (mode==='forward'?state.facts:state.goals)" :key="i" class="term-row">{{ f }}</li></ol><p v-if="mode==='sld'&&!state.goals.length">Danh sách rỗng.</p><p v-if="state.parents">Tiền đề khớp: {{ state.parents.join(' và ') }}</p><p v-if="state.rule">Luật đang xét: {{ state.rule }}.</p></article><article><h4>Phép thế của bước này</h4><p v-for="([v,t]) in Object.entries(state.theta||{})" :key="v" class="term-row">{{ v }} ↦ {{ t }}</p><p v-if="!Object.keys(state.theta||{}).length">Chưa có ràng buộc.</p><p v-if="state.depth!==undefined">Độ sâu nhánh {{ state.depth }}.</p></article></div><div class="inference-answers"><h4>Câu trả lời đã tìm</h4><p v-if="!state.answers.length">Chưa có câu trả lời.</p><p v-for="(answer,i) in state.answers" :key="i" class="term-row">{{ Object.keys(answer).length?Object.entries(answer).map(([v,t])=>v+' ↦ '+t).join(', '):'Truy vấn nền đã được chứng minh' }}</p></div><details><summary>Giới hạn và thứ tự duyệt</summary><p>Suy luận tiến quét luật theo thứ tự khai báo, ghép tiền đề từ trái sang phải và loại sự thực trùng. Dừng ở tối đa 60 sự thực hoặc 600 lần khớp luật. Có hàm tạo hạng thức thì bao đóng có thể vô hạn.</p><p>SLD chọn mục tiêu trái nhất, thử luật trước sự thực, chuẩn hóa biến mỗi lần dùng luật. Giới hạn độ sâu 12, 500 lượt gọi và 12 câu trả lời. Giới hạn giúp trình duyệt ổn định, không biến duyệt sâu thành thủ tục đầy đủ cho mọi cơ sở tri thức.</p></details><PredicateCode :name="mode==='forward'?'forwardPredicateSteps':'sldPredicateSteps'" :phase="state.phase"/></section></template>
<style scoped>
.predicate-inference{min-width:0}.infer-config{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.predicate-inference label{display:grid;gap:6px;font:var(--fs-small)/1.7 var(--font-ui)}.predicate-inference :is(select,textarea,button){min-height:44px;max-width:100%;min-width:0;padding:8px;border:1px solid var(--control);border-radius:var(--radius);background:var(--paper);color:var(--ink);font:inherit}.predicate-inference textarea{width:100%;font:13px/1.7 var(--font-code)}.query-term,.term-row{font:14px/1.8 var(--font-code);overflow-wrap:anywhere}.predicate-status{padding:12px;border-left:3px solid var(--tim);background:var(--tim-soft)}.inference-state{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.inference-state article,.inference-answers{padding:12px;min-width:0;border:1px solid var(--rule);border-radius:var(--radius);background:var(--paper)}.inference-state h4,.inference-answers h4{font:600 var(--fs-small)/1.6 var(--font-ui)}.inference-state ol{padding-left:22px}.inference-answers{margin:12px 0}summary{min-height:44px;cursor:pointer}:is(select,textarea,button,summary):focus-visible{outline:3px solid var(--tim);outline-offset:3px}@media(max-width:600px){.infer-config,.inference-state{grid-template-columns:1fr}}
</style>
